/**
 * Illustrative Gapminder-style series: real country names, modelled figures.
 * Each nation is a closed-form curve plus at most one setback, so the animation
 * is byte-identical on every reload without shipping 30 x 71 raw numbers.
 */

const START_YEAR = 1950;
const END_YEAR = 2020;

const YEARS: number[] = Array.from(
  { length: END_YEAR - START_YEAR + 1 },
  (_, i) => START_YEAR + i
);

const REGIONS = [
  'Sub-Saharan Africa',
  'Americas',
  'East Asia & Pacific',
  'Europe & Central Asia',
  'Middle East & North Africa'
] as const;

type Region = (typeof REGIONS)[number];

/** A setback that deepens to `peak` then recovers by `end`. */
type Setback = { start: number; peak: number; end: number; life?: number; income?: number };

type Params = {
  name: string;
  region: Region;
  income0: number;
  incomeGrowth: number;
  life0: number;
  lifeMax: number;
  lifeRate: number;
  pop0: number;
  popGrowth: number;
  setback?: Setback;
};

