type Nation = {
  name: string;
  region: Region;
  income: number[];
  life: number[];
  population: number[];
};

/** Triangular 0 -> 1 -> 0 pulse across the setback window. */
function pulse(year: number, s: Setback): number {
  if (year <= s.start || year >= s.end) return 0;
  return year < s.peak ? (year - s.start) / (s.peak - s.start) : (s.end - year) / (s.end - s.peak);
}

function toSeries(p: Params): Nation {
  const income: number[] = [];
  const life: number[] = [];
  const population: number[] = [];
  for (const year of YEARS) {
    const t = year - START_YEAR;
    const hit = p.setback ? pulse(year, p.setback) : 0;
    income.push(p.income0 * Math.exp(p.incomeGrowth * t) * (1 - (p.setback?.income ?? 0) * hit));
    life.push(
      p.lifeMax - (p.lifeMax - p.life0) * Math.exp(-p.lifeRate * t) - (p.setback?.life ?? 0) * hit
    );
    population.push(p.pop0 * Math.exp(p.popGrowth * t));
  }
  return { name: p.name, region: p.region, income, life, population };
}

const nations: Nation[] = PARAMS.map(toSeries);

const MARGIN = { top: 18, right: 20, bottom: 42, left: 46 };
const STEP_MS = 110;
const X_TICKS = [500, 1000, 2000, 5000, 10000, 20000, 50000];
const MAX_POPULATION = 1.4e9;

/**
 * One entry per nation, each series indexed by `years`, plus the region list the legend and
 * the colour scale enumerate.
 */
export type Data = {
  nations: {
    name: string;
    region: string;
    income: number[];
    life: number[];
    population: number[];
  }[];
  regions: readonly string[];
  years: number[];
};

const DEMO: Data = { nations, regions: REGIONS, years: YEARS };

export default function WealthHealthOfNations({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const [frame, setFrame] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setFrame((f) => (f + 1) % data.years.length), STEP_MS);
    return () => clearInterval(timer);
  }, [data]);

  const x = useMemo(() => d3.scaleLog([400, 100000], [0, innerWidth]), [innerWidth]);
  const y = useMemo(() => d3.scaleLinear([25, 90], [innerHeight, 0]), [innerHeight]);
  const radius = useMemo(() => d3.scaleSqrt([0, MAX_POPULATION], [0, width / 20]), [width]);
  const color = useMemo(
    () => d3.scaleOrdinal<string, string>(data.regions, d3.schemeObservable10),
    [data]
  );

  // Largest first, so the DOM order paints small nations on top of big ones.
  const points = useMemo(
    () =>
      data.nations
        .map((d) => ({
          name: d.name,
          region: d.region,
          income: d.income[frame],
          life: d.life[frame],
          population: d.population[frame]
        }))
        .sort((a, b) => d3.descending(a.population, b.population)),
    [data, frame]
  );

  const xTicks: Tick[] = useMemo(
    () => X_TICKS.map((v) => ({ value: d3.format('$~s')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  const showLegend = innerWidth >= 420;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label={`Animated scatterplot of illustrative income, life expectancy and population for 30 nations, showing ${data.years[frame]}`}>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <text x={innerWidth - 6} y={innerHeight - 10} textAnchor="end" fill="var(--muted)"
              fontSize={innerHeight * 0.38} fontWeight={700} opacity={0.14}>
          {data.years[frame]}
        </text>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {points.map((p) => (
          <motion.circle
            key={p.name}
            initial={false}
            animate={{ cx: x(p.income), cy: y(p.life), r: radius(p.population) }}
            transition={{ duration: STEP_MS / 1000, ease: 'linear' }}
            fill={color(p.region)}
            fillOpacity={0.72}
            stroke="var(--bg)"
            strokeWidth={0.75}
          >
            <title>{`${p.name}\n${p.region}`}</title>
          </motion.circle>
        ))}
        {showLegend &&
          data.regions.map((region, i) => (
            <g key={region} transform={`translate(2,${i * 15})`}>
              <rect width={10} height={10} rx={2} fill={color(region)} />
              <text x={15} y={9} fill="var(--muted)" fontSize={11}>
                {region}
              </text>
            </g>
          ))}
        <text x={0} y={-6} fill="var(--muted)" fontSize={11}>
          ↑ Life expectancy (years)
        </text>
        <text x={innerWidth} y={innerHeight + MARGIN.bottom - 6} textAnchor="end"
              fill="var(--muted)" fontSize={11}>
          Income per capita (illustrative dollars) →
        </text>
      </g>
    </svg>
  );
}
